SET NOCOUNT ON;
SELECT N'缺失面板' AS 问题, v.p AS 面板 FROM (VALUES (N'SO_ORDER'),(N'SALES_ORDER_DETAIL'),(N'SALES_ORDER_STATS'),(N'PU_REQ'),(N'PU_ORDER'),(N'QC_RECV'),(N'QC_RETURN'),(N'PURCHASE_IN'),(N'FINISH_IN'),(N'OTHER_IN'),(N'OUTSOURCE_IN'),(N'SALE_OUT'),(N'MATERIAL_OUT'),(N'OTHER_OUT'),(N'OUTSOURCE_ISSUE'),(N'PURCHASE_IN_DETAIL'),(N'FINISH_IN_DETAIL'),(N'OTHER_IN_DETAIL'),(N'OUTSOURCE_IN_DETAIL'),(N'SALE_OUT_DETAIL'),(N'MATERIAL_OUT_DETAIL'),(N'OTHER_OUT_DETAIL'),(N'OUTSOURCE_ISSUE_DETAIL'),(N'PURCHASE_IN_STATS'),(N'FINISH_IN_STATS'),(N'OTHER_IN_STATS'),(N'OUTSOURCE_IN_STATS'),(N'SALE_OUT_STATS'),(N'MATERIAL_OUT_STATS'),(N'OTHER_OUT_STATS'),(N'OUTSOURCE_ISSUE_STATS'),(N'STOCK_BALANCE'),(N'STOCK_LEDGER'),(N'STOCK_SUMMARY'),(N'QC_INSP'),(N'QC_TC_IN'),(N'QC_CATALOG'),(N'QC_INSP_REC'),(N'QC_INSP_REQ'),(N'QC_OP'),(N'QC_RECORD'),(N'QC_DISPOSAL'),(N'ROD_RETURN'),(N'LOT_TRACE'),(N'QC_BHG'),(N'QC_BHC'),(N'QC_BHZ'),(N'QC_JJF'),(N'QC_SCP'),(N'QC_LYB'),(N'QC_SCY')) v(p) WHERE NOT EXISTS (SELECT 1 FROM yj_panel WHERE panel_code = v.p);
SELECT N'无授权行' AS 问题, v.p AS 面板 FROM (VALUES (N'SO_ORDER'),(N'SALES_ORDER_DETAIL'),(N'SALES_ORDER_STATS'),(N'PU_REQ'),(N'PU_ORDER'),(N'QC_RECV'),(N'QC_RETURN'),(N'PURCHASE_IN'),(N'FINISH_IN'),(N'OTHER_IN'),(N'OUTSOURCE_IN'),(N'SALE_OUT'),(N'MATERIAL_OUT'),(N'OTHER_OUT'),(N'OUTSOURCE_ISSUE'),(N'PURCHASE_IN_DETAIL'),(N'FINISH_IN_DETAIL'),(N'OTHER_IN_DETAIL'),(N'OUTSOURCE_IN_DETAIL'),(N'SALE_OUT_DETAIL'),(N'MATERIAL_OUT_DETAIL'),(N'OTHER_OUT_DETAIL'),(N'OUTSOURCE_ISSUE_DETAIL'),(N'PURCHASE_IN_STATS'),(N'FINISH_IN_STATS'),(N'OTHER_IN_STATS'),(N'OUTSOURCE_IN_STATS'),(N'SALE_OUT_STATS'),(N'MATERIAL_OUT_STATS'),(N'OTHER_OUT_STATS'),(N'OUTSOURCE_ISSUE_STATS'),(N'STOCK_BALANCE'),(N'STOCK_LEDGER'),(N'STOCK_SUMMARY'),(N'QC_INSP'),(N'QC_TC_IN'),(N'QC_CATALOG'),(N'QC_INSP_REC'),(N'QC_INSP_REQ'),(N'QC_OP'),(N'QC_RECORD'),(N'QC_DISPOSAL'),(N'ROD_RETURN'),(N'LOT_TRACE'),(N'QC_BHG'),(N'QC_BHC'),(N'QC_BHZ'),(N'QC_JJF'),(N'QC_SCP'),(N'QC_LYB'),(N'QC_SCY')) v(p) WHERE NOT EXISTS (SELECT 1 FROM yj_role_panel WHERE panel_code = v.p);
SELECT N'面板总数' AS 项, CAST(COUNT(*) AS varchar(10)) AS 值 FROM yj_panel WHERE panel_code IN (SELECT p FROM (VALUES (N'SO_ORDER'),(N'SALES_ORDER_DETAIL'),(N'SALES_ORDER_STATS'),(N'PU_REQ'),(N'PU_ORDER'),(N'QC_RECV'),(N'QC_RETURN'),(N'PURCHASE_IN'),(N'FINISH_IN'),(N'OTHER_IN'),(N'OUTSOURCE_IN'),(N'SALE_OUT'),(N'MATERIAL_OUT'),(N'OTHER_OUT'),(N'OUTSOURCE_ISSUE'),(N'PURCHASE_IN_DETAIL'),(N'FINISH_IN_DETAIL'),(N'OTHER_IN_DETAIL'),(N'OUTSOURCE_IN_DETAIL'),(N'SALE_OUT_DETAIL'),(N'MATERIAL_OUT_DETAIL'),(N'OTHER_OUT_DETAIL'),(N'OUTSOURCE_ISSUE_DETAIL'),(N'PURCHASE_IN_STATS'),(N'FINISH_IN_STATS'),(N'OTHER_IN_STATS'),(N'OUTSOURCE_IN_STATS'),(N'SALE_OUT_STATS'),(N'MATERIAL_OUT_STATS'),(N'OTHER_OUT_STATS'),(N'OUTSOURCE_ISSUE_STATS'),(N'STOCK_BALANCE'),(N'STOCK_LEDGER'),(N'STOCK_SUMMARY'),(N'QC_INSP'),(N'QC_TC_IN'),(N'QC_CATALOG'),(N'QC_INSP_REC'),(N'QC_INSP_REQ'),(N'QC_OP'),(N'QC_RECORD'),(N'QC_DISPOSAL'),(N'ROD_RETURN'),(N'LOT_TRACE'),(N'QC_BHG'),(N'QC_BHC'),(N'QC_BHZ'),(N'QC_JJF'),(N'QC_SCP'),(N'QC_LYB'),(N'QC_SCY')) v(p));
SELECT N'授权行总数' AS 项, CAST(COUNT(*) AS varchar(10)) AS 值 FROM yj_role_panel WHERE panel_code IN (SELECT p FROM (VALUES (N'SO_ORDER'),(N'SALES_ORDER_DETAIL'),(N'SALES_ORDER_STATS'),(N'PU_REQ'),(N'PU_ORDER'),(N'QC_RECV'),(N'QC_RETURN'),(N'PURCHASE_IN'),(N'FINISH_IN'),(N'OTHER_IN'),(N'OUTSOURCE_IN'),(N'SALE_OUT'),(N'MATERIAL_OUT'),(N'OTHER_OUT'),(N'OUTSOURCE_ISSUE'),(N'PURCHASE_IN_DETAIL'),(N'FINISH_IN_DETAIL'),(N'OTHER_IN_DETAIL'),(N'OUTSOURCE_IN_DETAIL'),(N'SALE_OUT_DETAIL'),(N'MATERIAL_OUT_DETAIL'),(N'OTHER_OUT_DETAIL'),(N'OUTSOURCE_ISSUE_DETAIL'),(N'PURCHASE_IN_STATS'),(N'FINISH_IN_STATS'),(N'OTHER_IN_STATS'),(N'OUTSOURCE_IN_STATS'),(N'SALE_OUT_STATS'),(N'MATERIAL_OUT_STATS'),(N'OTHER_OUT_STATS'),(N'OUTSOURCE_ISSUE_STATS'),(N'STOCK_BALANCE'),(N'STOCK_LEDGER'),(N'STOCK_SUMMARY'),(N'QC_INSP'),(N'QC_TC_IN'),(N'QC_CATALOG'),(N'QC_INSP_REC'),(N'QC_INSP_REQ'),(N'QC_OP'),(N'QC_RECORD'),(N'QC_DISPOSAL'),(N'ROD_RETURN'),(N'LOT_TRACE'),(N'QC_BHG'),(N'QC_BHC'),(N'QC_BHZ'),(N'QC_JJF'),(N'QC_SCP'),(N'QC_LYB'),(N'QC_SCY')) v(p));
